import { readFileSync } from "fs";

const [t, p] = readFileSync(0, "utf8").trim().split("\n");

// fail[i] = P の先頭 i 文字で、接頭辞と接尾辞が一致する最大の長さ（自分自身は除く）
const fail = new Int32Array(p.length + 1);
fail[0] = -1;
for (let i = 0, j = -1; i < p.length; ) {
  while (j >= 0 && p[i] !== p[j]) j = fail[j];
  fail[++i] = ++j;
}

// KMP 法: 一致しなかったら、P の位置だけを fail で戻す（T の位置は戻さない）
const positions: number[] = [];
for (let i = 0, j = 0; i < t.length; i++) {
  while (j >= 0 && t[i] !== p[j]) j = fail[j];
  j++;
  if (j === p.length) {
    positions.push(i - p.length + 2); // 1 始まりの開始位置
    j = fail[j];
  }
}
console.log(positions.length > 0 ? positions.join(" ") : "-1");
